// Makes sure every label this workflow may apply exists:
// category labels, rule target labels and the "processed" marker label.
// Outputs one item per missing label (parents of nested "Parent/Child" labels first),
// or a single { create: false } item when nothing has to be created.
const cfg = $('Config').first().json;
const prefix = String(cfg.label_prefix || '');
const wanted = [];
const add = n => {
  n = String(n || '').trim();
  if (n && !wanted.some(w => w.toLowerCase() === n.toLowerCase())) wanted.push(n);
};
for (const c of (Array.isArray(cfg.categories) ? cfg.categories : [])) {
  const name = String((c && c.name) || '').trim();
  if (name) add(prefix + name);
}
for (const r of (Array.isArray(cfg.rules) ? cfg.rules : [])) {
  const name = String((r && r.category) || '').trim();
  if (name) add(prefix + name);
}
add(cfg.processed_label);
// Nested labels: make sure "Parent" exists before "Parent/Child"
for (const n of [...wanted]) {
  const parts = n.split('/');
  for (let i = 1; i < parts.length; i++) add(parts.slice(0, i).join('/'));
}
// Gmail label names are unique case-insensitively
const existing = new Set($input.all().map(i => String((i.json || {}).name || '').toLowerCase()).filter(Boolean));
const missing = cfg.create_missing_labels === false ? [] : wanted.filter(n => !existing.has(n.toLowerCase()));
missing.sort((a, b) => a.split('/').length - b.split('/').length);
if (!missing.length) return [{ json: { create: false } }];
return missing.map(name => ({ json: { create: true, name } }));

// One classification request per email.
// - Jev (default): a typed "choice" decision. The category names are fixed options, so the model
//   cannot return an invented category or broken JSON.
// - LLM (engine: "llm"): OpenRouter chat/completions with a JSON-schema enum answer.
// Deterministic rules (Config.rules) are evaluated here and win over the model in "Decide Labels".
// A model request is still built for every email so requests and responses stay aligned by index.
const cfg = $('Config').first().json;
const engine = String(cfg.engine || 'jev').toLowerCase();
const categories = Array.isArray(cfg.categories) ? cfg.categories : [];
const names = categories.map(c => String((c && c.name) || '').trim());

// Config sanity checks: fail loudly instead of labeling mail wrongly
if (!['jev', 'llm'].includes(engine)) throw new Error('Config.engine must be "jev" or "llm".');
if (names.length < 2) throw new Error('Config.categories needs at least 2 entries like {"name": "...", "criteria": "..."}.');
if (names.length > 255) throw new Error('Config.categories: a Jev "choice" question accepts at most 255 options.');
if (names.some(n => !n)) throw new Error('Config.categories: every category needs a non-empty "name".');
if (new Set(names.map(n => n.toLowerCase())).size !== names.length) throw new Error('Config.categories: names must be unique (case-insensitive).');

const criteria = {};
categories.forEach((c, i) => { criteria[names[i]] = String(c.criteria || names[i]).trim(); });
const QUESTION = { type: 'choice', instructions: String(cfg.instructions || ''), criteria };

// Rules: { field: from | subject | snippet | text | any, contains: "..." or regex: "...", category: "..." }
// "from" is the sender address only; "text" is subject + snippet; matching is case-insensitive; first match wins.
const FIELDS = ['from', 'subject', 'snippet', 'text', 'any'];
const RULES = (Array.isArray(cfg.rules) ? cfg.rules : []).map((r, i) => {
  const field = String(r.field || 'from').toLowerCase();
  if (!FIELDS.includes(field)) throw new Error(`Config.rules[${i}].field must be one of ${FIELDS.join(', ')}.`);
  const category = String(r.category || '').trim();
  if (!category) throw new Error(`Config.rules[${i}] needs a "category" (the label to apply).`);
  let test;
  if (r.regex) {
    let rx;
    try { rx = new RegExp(String(r.regex), 'i'); }
    catch (e) { throw new Error(`Config.rules[${i}].regex is not a valid regular expression: ${e.message}`); }
    test = s => rx.test(s);
  } else if (r.contains) {
    const needle = String(r.contains).toLowerCase();
    test = s => s.toLowerCase().includes(needle);
  } else {
    throw new Error(`Config.rules[${i}] needs "contains" or "regex".`);
  }
  return { field, test, category };
});
function rule(m) {
  const f = { from: m.fromAddr, subject: m.subject, snippet: m.snippet,
    text: m.subject + ' ' + m.snippet, any: m.fromAddr + ' ' + m.subject + ' ' + m.snippet };
  for (const r of RULES) if (r.test(f[r.field] || '')) return r.category;
  return '';
}

// Plain-LLM fallback for people without access to the Jev endpoint
const LLM_SYSTEM = [
  String(cfg.instructions || ''),
  '',
  'Categories (choose exactly one name):',
  ...names.map(n => `- ${n}: ${criteria[n]}`),
  '',
  'Reply only with JSON: {"category": "<one of the category names>"}',
].join('\n');
function llmBody(state) {
  return {
    model: cfg.llm_model,
    temperature: 0,
    messages: [
      { role: 'system', content: LLM_SYSTEM },
      { role: 'user', content: JSON.stringify(state) },
    ],
    response_format: {
      type: 'json_schema',
      json_schema: {
        name: 'email_category',
        strict: true,
        schema: {
          type: 'object',
          properties: { category: { type: 'string', enum: names } },
          required: ['category'],
          additionalProperties: false,
        },
      },
    },
    // Only route to providers that support structured outputs
    provider: { require_parameters: true },
  };
}

function extractAddress(from) {
  if (!from) return '';
  if (typeof from === 'object') {
    if (Array.isArray(from.value) && from.value[0] && from.value[0].address) return String(from.value[0].address).toLowerCase();
    if (from.address) return String(from.address).toLowerCase();
    if (from.text) from = from.text;
  }
  const s = String(from);
  const m = s.match(/<([^>]+)>/);
  return m ? m[1].toLowerCase() : s.toLowerCase().trim();
}
function stringifyVal(v) {
  if (!v) return '';
  if (typeof v === 'object') return v.text || v.value || JSON.stringify(v).substring(0, 200);
  return String(v);
}

const out = [];
for (const it of $input.all()) {
  const e = it.json || {};
  if (!e.id) continue;
  const headers = (e.payload && Array.isArray(e.payload.headers)) ? e.payload.headers : [];
  const getH = n => { const h = headers.find(x => (x.name || '').toLowerCase() === n.toLowerCase()); return h ? (h.value || '') : ''; };
  const subject = stringifyVal(e.subject || e.Subject || getH('Subject')).substring(0, 150);
  const fromRaw = e.from || e.From || getH('From') || '';
  const fromAddr = extractAddress(fromRaw) || stringifyVal(fromRaw);
  const snippet = stringifyVal(e.snippet || '').substring(0, 150);
  const m = { id: e.id, fromAddr, subject, snippet };
  const state = { from: fromAddr, subject, snippet };
  const body = engine === 'llm'
    ? llmBody(state)
    : { model: cfg.jev_model || 'typesafe/jev-1.13', state, questions: { category: QUESTION } };
  out.push({ json: { ...m, rule: rule(m), body } });
}
return out;

// Pairs each request with its response (same order), resolves Gmail label IDs and decides what to apply.
// If the model was unreachable (or gave no valid category) nothing is applied: the email does not get the
// processed label, so the next run picks it up again.
const cfg = $('Config').first().json;
const engine = String(cfg.engine || 'jev').toLowerCase();
const prefix = String(cfg.label_prefix || '');
const names = (Array.isArray(cfg.categories) ? cfg.categories : []).map(c => String((c && c.name) || '').trim());

const labelIds = {};
const collect = items => {
  for (const l of items) { const j = l.json || {}; if (j.name && j.id) labelIds[String(j.name).toLowerCase()] = j.id; }
};
collect($('List Labels').all());
try { collect($('Create Label').all()); } catch (e) { /* Create Label did not run: nothing was missing */ }
const idFor = name => labelIds[String(name || '').trim().toLowerCase()] || null;
const DONE = idFor(cfg.processed_label);

function modelAnswer(json) {
  const none = { category: '', confidence: null, cost: null };
  if (!json || json.error) return none;
  const cost = (json.usage && typeof json.usage.cost === 'number') ? json.usage.cost : null;
  if (engine === 'llm') {
    const msg = json.choices && json.choices[0] && json.choices[0].message;
    let category = '';
    try {
      const raw = String((msg && msg.content) || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '');
      category = String(JSON.parse(raw).category || '').trim();
    } catch (e) { category = ''; }
    return { category: names.includes(category) ? category : '', confidence: null, cost };
  }
  const a = json.answers && json.answers.category;
  const category = (a && typeof a.choice === 'string') ? a.choice : '';
  return { category: names.includes(category) ? category : '',
    confidence: (a && typeof a.confidence === 'number') ? a.confidence : null, cost };
}

const reqs = $('Build Requests').all();
const res = $input.all();
const out = [];
reqs.forEach((r, k) => {
  const m = r.json;
  const ans = modelAnswer(res[k] && res[k].json);
  const category = m.rule || ans.category;
  if (!category) return; // model unreachable / invalid answer -> retried next run
  const label = prefix + category;
  const catId = idFor(label);
  if (!catId) return; // label missing (creation disabled or failed) -> retried once it exists
  const ids = [catId];
  if (DONE) ids.push(DONE);
  out.push({ json: { email_id: m.id, category, label, source: m.rule ? 'rule' : engine,
    confidence: m.rule ? 1 : ans.confidence, cost: ans.cost, from: m.fromAddr, subject: m.subject, labelIds: ids } });
});
return out;
